# Initially generated by GitHub Copilot.
"""Compare two git revisions of MAM-parsed-plus/ JSON and generate an HTML
diff report with category filtering.

Usage:
    .venv/Scripts/python.exe py/main_diff.py mpplus
    .venv/Scripts/python.exe py/main_diff.py mpplus --old <rev> --new <rev>
    .venv/Scripts/python.exe py/main_diff.py mpplus --all

Named historical releases read tracked MAM-parsed/historical/ snapshots.
HEAD and other MAM-basics Git refs read committed MAM-parsed/plus/ data.
Use --legacy-history with --old and --new for arbitrary revisions in a sibling
MAM-parsed clone. That rare mode requires read access and never fetches or clones.
Output goes to gh-pages/MAM-with-doc/change-log/ by default. If the hash range
matches an entry in releases.json, the release name is used as the filename;
otherwise the sanitised hash range is used.

The --all flag generates reports for every named release in releases.json
and regenerates index.html, including unpinned-latest when unreleased diffs exist.

When run with no arguments, the script compares the latest named release against
HEAD and writes gh-pages/MAM-with-doc/change-log/unpinned-latest.html when that
comparison produces diffs. When unreleased diffs are absent, the unpinned-latest
artifacts are rewritten as empty reports so stale content is not left behind.

WHICH RELEASE IS THE LATEST IS READ OFF releases.json RATHER THAN OUT OF GIT,
and that is what lets this program run in a shallow clone -- see
_latest_release_entry for the chain walk that replaced a commit count, and
Ben's decision of 2026-09-11 behind it.
"""

import argparse
import json
import os

from mb_cmn import paths
from mb_diff_mpu import (
    mpplus_classify,
    mpplus_extract,
    mpplus_html,
    mpplus_index,
    mpplus_json,
    mpplus_revisions,
)

CHANGE_LOG_DIR = str(paths.repo_root() / "gh-pages" / "MAM-with-doc" / "change-log")
RELEASES_JSON = f"{CHANGE_LOG_DIR}/releases.json"
UNPINNED_LATEST_HTML = f"{CHANGE_LOG_DIR}/unpinned-latest.html"
UNPINNED_LATEST_JSON = UNPINNED_LATEST_HTML.removesuffix(".html") + ".json"
PRESERVED_CHANGE_LOG_ARTIFACTS = (
    UNPINNED_LATEST_HTML,
    UNPINNED_LATEST_JSON,
)


def _commit_date(rev):
    """Return a stored release's or legacy:<ref>'s date, or "" for a MAM-basics ref.

    A MAM-basics ref has had no date since 2026-09-14, when it began to be recorded by the git
    tree id of MAM-parsed/plus.  Until then its date was that of the last commit to change
    MAM-parsed/plus, found by a path-filtered ``git log --full-history -1``, and in a shallow clone that walk can
    return the wrong commit.  Git treats each commit listed in .git/shallow as having no
    parents, so every path in it looks added, and the newest-first walk returns such a boundary
    commit whenever one is newer than the last real change.  This docstring had predicted a
    different failure, a walk that finds nothing and falls back to HEAD's own date; a cloud
    container's mega run showed on 2026-09-14 that the walk finds a boundary commit instead,
    whose hash and date the report then published over correct diffs.
    ``mpplus_revisions.resolve`` has the rest.
    """
    return mpplus_revisions.resolve(rev).date


def _sanitize_rev(rev):
    """Make a revision string safe for use in a filename."""
    return (
        rev.replace("/", "_")
        .replace("\\", "_")
        .replace(":", "_")
        .replace("..", "_")
        .replace("^", "-")[:20]
    )


def _lookup_release_name(old_rev, new_rev):
    """Return the release name if this hash range is in releases.json, else None."""
    if not os.path.isfile(RELEASES_JSON):
        return None
    with open(RELEASES_JSON, "r", encoding="utf-8") as in_fp:
        releases = json.load(in_fp)
    for entry in releases["releases"]:
        if entry["old"] == old_rev and entry["new"] == new_rev:
            return entry["name"]
    return None


def _latest_release_entry():
    """The terminal entry of releases.json's chain: the one no other entry continues.

    NO GIT AT ALL, WHICH IS THE POINT.  Until 2026-09-11 this counted, for each entry, the
    commits between its ``new`` boundary and HEAD, and took the smallest -- which needed
    ``MAM-parsed/historical/manifest.json``'s ``migration.landing_commit`` to be reachable.
    In a shallow clone it is not: measured in a cloud container on 2026-09-11, that clone held
    221 commits, ``git cat-file -t 63cf6c98`` could not find the landing commit, and the count
    died with ``fatal: Invalid revision range``.  So ``diff-mpplus``, step 6 of the mega's 60,
    could not run in the cloud at all.

    Ben's decision, 2026-09-11, on being told what the count was for: do the proposed work to
    make this compatible with a shallow clone.  The chain walk is that work.  ``releases.json``
    already declares itself a chain -- its own header says "Consecutive releases share a
    boundary: the 'new' of one release equals the 'old' of the next" -- so the latest release
    is the entry whose ``new`` is no other entry's ``old``, which is a property of the file
    rather than of the checkout.  Measured the same day, the five entries form one unbroken
    chain from ``2025-03-19a`` to ``2026-04-14``, with exactly one terminal entry.

    This is also the more faithful reading of "latest".  A commit count answers "whose boundary
    is nearest HEAD", which is the same answer only while the file is a chain; the chain walk
    answers the question actually being asked, and says so loudly when the file stops being one.
    """
    with open(RELEASES_JSON, "r", encoding="utf-8") as in_fp:
        releases = json.load(in_fp)["releases"]
    if not releases:
        return None
    continued = {entry["old"] for entry in releases}
    terminal = [entry for entry in releases if entry["new"] not in continued]
    if len(terminal) != 1:
        raise RuntimeError(
            f"releases.json is not a single chain: {len(terminal)} of its"
            f" {len(releases)} entries end one"
            f" ({', '.join(entry['name'] for entry in terminal) or 'none'})."
            " Exactly one entry's 'new' must be no other entry's 'old'."
        )
    return terminal[0]


def default_output_path(old_rev, new_rev):
    """Build the default output path inside the change-log directory."""
    name = _lookup_release_name(old_rev, new_rev)
    if name is not None:
        slug = name
    else:
        slug = f"{_sanitize_rev(old_rev)}_{_sanitize_rev(new_rev)}"
    return f"{CHANGE_LOG_DIR}/{slug}.html"


def generate_report(old_rev, new_rev, output, *, write_when_empty=True):
    """Generate one diff report. Returns the expanded diff count.

    The report never records a revision as given. Until 2026-09-11 it recorded
    ``old_rev`` and ``new_rev`` verbatim, so unpinned-latest said "HEAD", which names
    nothing once the report is committed; Ben decided that day that "a true hash should
    be recorded". A stored release or a legacy:<ref> records the full hash of its
    MAM-parsed commit. A MAM-basics ref recorded its content commit until 2026-09-14,
    and since then records the git tree id of MAM-parsed/plus, which is the same in
    every clone, shallow ones included; ``mpplus_revisions.resolve`` says why. The log
    need not keep up with every commit -- Ben, 2026-09-11: "I want the diff to be able
    to run as sparsely or as frequently as the user wants" -- so a report that lags only
    has to say exactly what it describes, and the recorded ids say it.
    """
    print(f"Comparing {old_rev} -> {new_rev} ...")
    diffs = mpplus_extract.diff_all_books(old_rev, new_rev)
    print(f"  {len(diffs)} raw changes found")
    if not diffs and not write_when_empty:
        print("  No diffs found; not writing report")
        return 0, _commit_date(old_rev)
    mpplus_classify.classify_diffs(diffs)
    from mb_diff_mpu import mpplus_verify

    verification_errors = mpplus_verify.verify_all(diffs)
    if verification_errors:
        raise mpplus_verify.VerificationError(
            f"{len(verification_errors)} diff(s) failed roundtrip verification; "
            "no JSON or HTML report was written"
        )
    old = mpplus_revisions.resolve(old_rev)
    new = mpplus_revisions.resolve(new_rev)
    os.makedirs(os.path.dirname(output), exist_ok=True)
    json_path = output.removesuffix(".html") + ".json"
    mpplus_json.write_json(diffs, old.label, new.label, json_path)
    print(f"  JSON written to {json_path}")
    total = mpplus_html.write_report(
        diffs, old.label, new.label, output, old.date, new.date
    )
    print(f"  Report written to {output}")
    return total, old.date


def run_all():
    """Generate reports for named releases plus unpinned-latest, then write index."""
    with open(RELEASES_JSON, "r", encoding="utf-8") as in_fp:
        data = json.load(in_fp)
    release_info = []
    for entry in data["releases"]:
        output = f"{CHANGE_LOG_DIR}/{entry['name']}.html"
        count, old_date = generate_report(entry["old"], entry["new"], output)
        release_info.append(
            {"name": entry["name"], "count": count, "old_date": old_date}
        )
    unpinned_info = run_unpinned_latest()
    if unpinned_info is not None:
        release_info.append(unpinned_info)
    mpplus_index.write_index(release_info, CHANGE_LOG_DIR)


def run_unpinned_latest():
    """Generate unpinned-latest report and return its index entry, else None.

    ONE BRANCH, NOT TWO.  Until 2026-09-11 a commit count was taken first and a zero sent the
    run down a separate path -- which called ``generate_report`` with byte-identical arguments
    and also returned None after writing the same empty artifacts.  The count therefore bought
    nothing but which of two "wrote empty artifacts" messages was printed, since the diff was
    computed either way; the two tests that covered the two paths asserted the same call and
    the same result, which is the same fact stated twice.  Ben's decision, 2026-09-11: remove
    it.  ``count``, which ``generate_report`` returns, is the honest test of "is there anything
    to report", and it is measured rather than predicted.
    """
    latest_release = _latest_release_entry()
    if latest_release is None:
        raise RuntimeError("releases.json has no release entries")
    old_rev = latest_release["new"]
    count, old_date = generate_report(
        old_rev,
        "HEAD",
        UNPINNED_LATEST_HTML,
        write_when_empty=True,
    )
    if count == 0:
        print(
            f"No diffs after the latest named release ({old_rev}); wrote empty "
            f"unpinned-latest artifacts: {', '.join(PRESERVED_CHANGE_LOG_ARTIFACTS)}"
        )
        return None
    return {"name": "unpinned-latest", "count": count, "old_date": old_date}


def add_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--all",
        action="store_true",
        help="Generate all named releases from releases.json and regenerate index.html",
    )
    parser.add_argument("--old", help="Stored release or MAM-basics revision")
    parser.add_argument("--new", help="Stored release or MAM-basics revision")
    parser.add_argument(
        "--legacy-history",
        action="store_true",
        help="Read both explicit revisions from a sibling MAM-parsed clone; never fetch or clone",
    )
    parser.add_argument(
        "--output",
        default=None,
        help="Output HTML path (default: auto from releases.json or hash range)",
    )


def run_from_args(args: argparse.Namespace) -> None:
    if args.legacy_history and (args.all or not args.old or not args.new):
        raise SystemExit(
            "--legacy-history requires --old and --new and cannot accompany --all"
        )
    if args.all:
        if args.old or args.new or args.output:
            raise SystemExit("--all cannot be combined with --old, --new, or --output")
        run_all()
        return
    if args.old or args.new:
        if not args.old or not args.new:
            raise SystemExit("--old and --new must be provided together")
        prefix = "legacy:" if args.legacy_history else ""
        old_rev = prefix + args.old
        new_rev = prefix + args.new
        output = args.output or default_output_path(old_rev, new_rev)
        generate_report(old_rev, new_rev, output)
        return
    if args.output:
        raise SystemExit("--output requires --old and --new")
    run_unpinned_latest()
